//! Immutable official artifact inventory for the complete local OCR pipeline.
//! Runtime locks are generated by the maintainer tool, never supplied by IPC.
use crate::ocr::{error, Code, Result};
use serde::{Deserialize, Serialize};
use sha2::{Digest, Sha256};
use std::path::Path;

pub const PIPELINE: &str = "PaddleOCR-VL-1.6";
pub const WORKER: &[u8] = include_bytes!("../../tools/ocr-runtime/worker.py");
const WINDOWS: &str = include_str!("../../tools/ocr-runtime/windows-x64.lock.json");
const LINUX: &str = include_str!("../../tools/ocr-runtime/linux-x64.lock.json");
// The exact reference catalog is shared with native qualification. Mac ARM64
// release registration requires the successful native lifetime run recorded
// in tools/ocr-runtime/README.md; Intel remains unsupported.
#[cfg(any(test, all(target_os = "macos", target_arch = "aarch64")))]
const MAC_REFERENCE: &str = include_str!("../../tools/ocr-runtime/macos-arm64.reference.lock.json");
#[cfg(any(test, all(target_os = "macos", target_arch = "aarch64")))]
const MAC_REFERENCE_INFO: &str =
    include_str!("../../tools/ocr-runtime/macos-arm64.inventory-reference.json");
#[cfg(any(test, all(target_os = "macos", target_arch = "aarch64")))]
const MAC_SOURCES: &str = include_str!("../../tools/ocr-runtime/macos-arm64.sources.lock.json");

#[derive(Clone, Copy, Debug, Deserialize, PartialEq, Eq)]
#[serde(rename_all = "camelCase")]
pub enum Kind {
    Python,
    PythonTarGz,
    Wheel,
    Model,
}
#[derive(Clone, Debug, Deserialize)]
pub struct Asset {
    pub kind: Kind,
    pub path: String,
    pub url: String,
    pub bytes: u64,
    pub sha256: String,
}
#[derive(Clone, Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct Catalog {
    pub schema: u32,
    pub target: String,
    pub pipeline: String,
    pub executable: String,
    pub bootstrap_path: String,
    pub bootstrap: String,
    #[serde(default)]
    pub bootstrap_entrypoint: bool,
    pub worker_sha256: String,
    pub inventory_sha256: String,
    pub file_count: usize,
    pub expanded_bytes: u64,
    pub assets: Vec<Asset>,
}
#[derive(Clone, Debug, Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
pub struct Entry {
    pub path: String,
    pub bytes: u64,
    pub sha256: String,
}
pub fn digest(bytes: &[u8]) -> String {
    format!("{:x}", Sha256::digest(bytes))
}
pub fn is_hash(value: &str) -> bool {
    value.len() == 64
        && value
            .bytes()
            .all(|c| c.is_ascii_digit() || (b'a'..=b'f').contains(&c))
}
pub fn relative(value: &str) -> Result<&Path> {
    if value.is_empty()
        || value.len() > 2048
        || value
            .chars()
            .any(|c| c.is_control() || "\\:<>\"|?*".contains(c))
        || value.split('/').any(|part| {
            let stem = part.split('.').next().unwrap_or("").to_ascii_uppercase();
            part.is_empty()
                || matches!(part, "." | "..")
                || part.ends_with(['.', ' '])
                || matches!(stem.as_str(), "CON" | "PRN" | "AUX" | "NUL")
                || ["COM", "LPT"].iter().any(|prefix| {
                    stem.strip_prefix(prefix).is_some_and(|tail| {
                        matches!(tail, "1" | "2" | "3" | "4" | "5" | "6" | "7" | "8" | "9")
                    })
                })
        })
    {
        return Err(error(Code::InvalidInput));
    }
    Ok(Path::new(value))
}
pub fn for_target(target: &str) -> Result<Catalog> {
    let raw = match target {
        "windows-x64" => WINDOWS,
        "linux-x64" => LINUX,
        // The pinned numpy/scipy/torch wheels require macOS 14 or newer.
        #[cfg(all(target_os = "macos", target_arch = "aarch64"))]
        "macos-arm64" if objc2::available!(macos = 14.0) => {
            return macos_reference_catalog();
        }
        _ => return Err(error(Code::Unavailable)),
    };
    parse_catalog(raw, target)
}
fn parse_catalog(raw: &str, target: &str) -> Result<Catalog> {
    let catalog: Catalog = serde_json::from_str(raw).map_err(|_| error(Code::Failed))?;
    if catalog.schema != 1
        || catalog.target != target
        || catalog.pipeline != PIPELINE
        || catalog.assets.is_empty()
        || catalog.assets.len() > 256
        || catalog.file_count > 60_000
        || catalog.expanded_bytes > 8 << 30
        || !is_hash(&catalog.inventory_sha256)
        || digest(WORKER) != catalog.worker_sha256
    {
        return Err(error(Code::Failed));
    }
    relative(&catalog.executable)?;
    relative(&catalog.bootstrap_path)?;
    let mut seen = std::collections::HashSet::new();
    for asset in &catalog.assets {
        relative(&asset.path)?;
        let url = reqwest::Url::parse(&asset.url).map_err(|_| error(Code::Failed))?;
        if url.scheme() != "https"
            || url.port().is_some()
            || !url.username().is_empty()
            || url.password().is_some()
            || !matches!(
                url.host_str(),
                Some(
                    "www.python.org"
                        | "github.com"
                        | "files.pythonhosted.org"
                        | "download.pytorch.org"
                        | "download-r2.pytorch.org"
                        | "huggingface.co"
                )
            )
            || asset.bytes == 0
            || asset.bytes > 2 << 30
            || !is_hash(&asset.sha256)
            || !seen.insert(asset.path.to_ascii_lowercase())
        {
            return Err(error(Code::Failed));
        }
    }
    Ok(catalog)
}
#[cfg(any(test, all(target_os = "macos", target_arch = "aarch64")))]
pub(crate) fn macos_reference_catalog() -> Result<Catalog> {
    checked_macos_reference(MAC_REFERENCE)
}
#[cfg(any(test, all(target_os = "macos", target_arch = "aarch64")))]
fn checked_macos_reference(raw: &str) -> Result<Catalog> {
    let expected: serde_json::Value =
        serde_json::from_str(MAC_REFERENCE_INFO).map_err(|_| error(Code::Failed))?;
    let source_sha = digest(MAC_SOURCES.as_bytes());
    let catalog_sha = digest(raw.as_bytes());
    if expected["referenceOnly"] != true
        || expected["nativeValidated"] != false
        || expected["target"] != "macos-arm64"
        || expected["sourceLockSha256"].as_str() != Some(source_sha.as_str())
        || expected["catalogSha256"].as_str() != Some(catalog_sha.as_str())
    {
        return Err(error(Code::Failed));
    }
    let catalog = parse_catalog(raw, "macos-arm64")?;
    if expected["inventorySha256"].as_str() != Some(catalog.inventory_sha256.as_str())
        || expected["workerSha256"].as_str() != Some(catalog.worker_sha256.as_str())
        || expected["fileCount"].as_u64() != Some(catalog.file_count as u64)
        || expected["expandedBytes"].as_u64() != Some(catalog.expanded_bytes)
        || !catalog.bootstrap_entrypoint
        || catalog.executable != "python/bin/python3.13"
        || catalog.bootstrap_path != "bootstrap.py"
    {
        return Err(error(Code::Failed));
    }
    Ok(catalog)
}
pub fn target() -> &'static str {
    if cfg!(all(windows, target_arch = "x86_64")) {
        "windows-x64"
    } else if cfg!(all(target_os = "macos", target_arch = "aarch64")) {
        "macos-arm64"
    } else if cfg!(target_os = "macos") {
        "macos-x64"
    } else if cfg!(target_arch = "aarch64") {
        "linux-arm64"
    } else {
        "linux-x64"
    }
}
impl Catalog {
    pub fn directory(&self) -> String {
        format!(
            "paddle-v1.6-{}-{}",
            self.target,
            &self.inventory_sha256[..16]
        )
    }
    pub fn total_bytes(&self) -> u64 {
        self.assets.iter().map(|asset| asset.bytes).sum()
    }
    pub fn validate_inventory(&self, files: &[Entry]) -> Result<()> {
        if files.len() != self.file_count {
            return Err(error(Code::Failed));
        }
        let mut sorted: Vec<_> = files.iter().collect();
        sorted.sort_unstable_by(|a, b| a.path.cmp(&b.path));
        let mut seen = std::collections::HashSet::new();
        let mut hash = Sha256::new();
        let mut total = 0u64;
        for entry in sorted {
            relative(&entry.path)?;
            let identity = if self.target.starts_with("windows-") {
                entry.path.to_ascii_lowercase()
            } else {
                entry.path.clone()
            };
            if !is_hash(&entry.sha256) || !seen.insert(identity) {
                return Err(error(Code::Failed));
            }
            total = total
                .checked_add(entry.bytes)
                .ok_or_else(|| error(Code::LimitExceeded))?;
            hash.update(format!(
                "{}\0{}\0{}\n",
                entry.path, entry.bytes, entry.sha256
            ));
        }
        if total != self.expanded_bytes || format!("{:x}", hash.finalize()) != self.inventory_sha256
        {
            return Err(error(Code::Failed));
        }
        Ok(())
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn macos_reference_is_bound_to_the_verified_sources() {
        let catalog = macos_reference_catalog().unwrap();
        let sources: serde_json::Value = serde_json::from_str(MAC_SOURCES).unwrap();
        assert_eq!(
            catalog.assets.len(),
            sources["assets"].as_array().unwrap().len()
        );
        for asset in &catalog.assets {
            let source = sources["assets"]
                .as_array()
                .unwrap()
                .iter()
                .find(|item| item["path"] == asset.path)
                .unwrap();
            assert_eq!(source["sha256"], asset.sha256);
            assert_eq!(source["bytes"].as_u64(), Some(asset.bytes));
            assert_eq!(source["url"], asset.url);
        }
        assert!(checked_macos_reference("{}").is_err());
        let altered = MAC_REFERENCE.replacen("36322", "36323", 1);
        assert!(checked_macos_reference(&altered).is_err());
        // Host-independent parsing is data validation, not Mac availability.
        #[cfg(not(all(target_os = "macos", target_arch = "aarch64")))]
        assert_eq!(
            for_target("macos-arm64").unwrap_err().code,
            Code::Unavailable
        );
    }
    #[cfg(all(target_os = "macos", target_arch = "aarch64"))]
    #[test]
    fn macos_catalog_needs_a_supported_os_and_no_qualification_flag() {
        const CHILD: &str = "PRISM_TEST_MAC_CATALOG_CHILD";
        if std::env::var(CHILD).as_deref() == Ok("1") {
            assert_eq!(
                for_target("macos-arm64").is_ok(),
                objc2::available!(macos = 14.0),
            );
            assert_eq!(for_target("macos-x64").unwrap_err().code, Code::Unavailable);
            return;
        }
        // Check our own test child without mutating this process's environment,
        // even when a qualification workflow still supplies the old flag.
        let output = std::process::Command::new(std::env::current_exe().unwrap())
            .args([
                "ocr_assets::tests::macos_catalog_needs_a_supported_os_and_no_qualification_flag",
                "--exact",
                "--nocapture",
            ])
            .env_remove("PRISM_DEV_PADDLE_REFERENCE")
            .env(CHILD, "1")
            .output()
            .unwrap();
        assert!(
            output.status.success(),
            "catalog child failed: {} {}",
            String::from_utf8_lossy(&output.stdout),
            String::from_utf8_lossy(&output.stderr),
        );
    }
    #[test]
    fn official_catalog_pins_the_complete_pipeline_and_worker() {
        let catalog = for_target("windows-x64").unwrap();
        assert_eq!(
            catalog
                .assets
                .iter()
                .filter(|a| a.kind == Kind::Model)
                .count(),
            21
        );
        assert!(catalog
            .assets
            .iter()
            .any(|a| a.path == "models/layout/model.safetensors"));
        assert!(catalog
            .assets
            .iter()
            .any(|a| a.path == "models/vlm/model.safetensors"));
        assert_eq!(catalog.worker_sha256, digest(WORKER));
        assert!(catalog.total_bytes() > 2_000_000_000);
        assert_eq!(for_target("unknown").unwrap_err().code, Code::Unavailable);
    }
    #[test]
    fn unsafe_members_and_untrusted_inventory_are_rejected() {
        for path in [
            "../escape",
            "/root",
            "x//y",
            "C:/file",
            "a\\b",
            "con.txt",
            "a/./x",
            "x.",
            "x/COM1.dat",
            "a\0b",
        ] {
            assert!(relative(path).is_err(), "{path:?}");
        }
        let catalog = for_target("windows-x64").unwrap();
        assert!(catalog.validate_inventory(&[]).is_err());
        let fake = vec![
            Entry {
                path: "python/python.exe".into(),
                bytes: 1,
                sha256: digest(b"x")
            };
            catalog.file_count
        ];
        assert!(catalog.validate_inventory(&fake).is_err());
    }
    #[test]
    fn linux_catalog_contains_the_same_models_and_a_private_unix_bootstrap() {
        let linux = for_target("linux-x64").unwrap();
        let windows = for_target("windows-x64").unwrap();
        assert!(linux.bootstrap_entrypoint && !windows.bootstrap_entrypoint);
        assert_eq!(linux.executable, "python/bin/python3.13");
        assert_eq!(linux.bootstrap_path, "bootstrap.py");
        assert!(linux.assets.iter().any(|a| a.kind == Kind::PythonTarGz));
        for model in windows.assets.iter().filter(|a| a.kind == Kind::Model) {
            let other = linux.assets.iter().find(|a| a.path == model.path).unwrap();
            assert_eq!(model.sha256, other.sha256);
            assert_eq!(model.bytes, other.bytes);
        }
    }
    #[test]
    fn inventory_case_identity_is_platform_specific() {
        let files = vec![
            Entry {
                path: "python/a.py".into(),
                bytes: 1,
                sha256: digest(b"x"),
            },
            Entry {
                path: "python/A.py".into(),
                bytes: 1,
                sha256: digest(b"x"),
            },
        ];
        let sha = digest(
            format!(
                "python/A.py\0{}\0{}\npython/a.py\0{}\0{}\n",
                1,
                digest(b"x"),
                1,
                digest(b"x")
            )
            .as_bytes(),
        );
        for target in ["windows-x64", "linux-x64"] {
            let mut catalog = for_target(target).unwrap();
            catalog.file_count = 2;
            catalog.expanded_bytes = 2;
            catalog.inventory_sha256 = sha.clone();
            assert_eq!(
                catalog.validate_inventory(&files).is_ok(),
                target == "linux-x64"
            );
        }
    }
}
